const visual = {
  prepare: function (input) {
    return [];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var n = 5;
    var margin = Math.min(W, H) * 0.08;
    var size = Math.min(W - margin * 2, H - margin * 2);
    if (!(size > 0)) {
      size = Math.min(W, H) * 0.8;
    }
    var x0 = (W - size) / 2;
    var y0 = (H - size) / 2;
    var step = size / n;
    var paths = [];
    var children = [];
    var i;
    for (i = 0; i <= n; i++) {
      var x = x0 + i * step;
      var vid = 'grid-v-' + i;
      paths.push({ id: vid, commands: [['M', x, y0], ['L', x, y0 + size]] });
      children.push({ type: 'path', pathId: vid, fill: '#26354A', stroke: { width: 2, cap: 'butt' } });
    }
    for (i = 0; i <= n; i++) {
      var y = y0 + i * step;
      var hid = 'grid-h-' + i;
      paths.push({ id: hid, commands: [['M', x0, y], ['L', x0 + size, y]] });
      children.push({ type: 'path', pathId: hid, fill: '#26354A', stroke: { width: 2, cap: 'butt' } });
    }
    return {
      schemaVersion: 1,
      sceneId: 'grid-5x5',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
